export class OrderService {
  private emailService: EmailService;
  private inventoryService: InventoryService;
  private paymentService: PaymentService;

  constructor() {
    this.emailService = new EmailService();
    this.inventoryService = new InventoryService();
    this.paymentService = new PaymentService();
  }

  async processOrder(orderId: string, customerId: string, items: any[], paymentMethod: string, shippingAddress: string, promoCode: string, isGuestCheckout: boolean) {
    // Validate items
    for (const item of items) {
      if (!item.id || !item.quantity || item.quantity < 1) {
        throw new Error('Invalid item');
      }
      const inStock = await this.inventoryService.checkStock(item.id, item.quantity);
      if (!inStock) throw new Error(`Item ${item.id} out of stock`);
    }

    // Calculate price
    let total = 0;
    for (const item of items) {
      const price = await db.query('SELECT price FROM products WHERE id = $1', [item.id]);
      total += price.rows[0].price * item.quantity;
    }
    if (promoCode) {
      const promo = await db.query('SELECT discount FROM promos WHERE code = $1', [promoCode]);
      if (promo.rows.length) total *= (1 - promo.rows[0].discount);
    }

    // Process payment
    const payment = await this.paymentService.charge(customerId, total, paymentMethod);
    if (!payment.success) throw new Error('Payment failed');

    // Save order
    const order = await db.query(
      'INSERT INTO orders (customer_id, total, shipping_address, promo_code) VALUES ($1, $2, $3, $4) RETURNING id',
      [customerId, total, shippingAddress, promoCode]
    );

    // Update inventory
    for (const item of items) {
      await this.inventoryService.decrementStock(item.id, item.quantity);
    }

    // Notify
    if (isGuestCheckout) {
      await this.emailService.sendGuestOrderConfirmation(shippingAddress, order.rows[0].id);
    } else {
      const customer = await db.query('SELECT email FROM customers WHERE id = $1', [customerId]);
      await this.emailService.sendOrderConfirmation(customer.rows[0].email, order.rows[0].id);
    }

    return order.rows[0].id;
  }

  async getOrder(orderId: string) {
    return db.query('SELECT * FROM orders WHERE id = $1', [orderId]);
  }

  async cancelOrder(orderId: string) {
    const order = await db.query('SELECT * FROM orders WHERE id = $1', [orderId]);
    if (order.rows[0].status === 'shipped') throw new Error('Cannot cancel shipped order');
    await db.query('UPDATE orders SET status = $1 WHERE id = $2', ['cancelled', orderId]);
    for (const item of order.rows[0].items) {
      await this.inventoryService.incrementStock(item.id, item.quantity);
    }
  }
