        raise ValueError(f'Unknown notification type: {notif_type}')
    return result


def send_bulk_notifications(user_ids, message, notif_type, priority=None, retry_count=3, dry_run=False):
    results = {}
    for uid in user_ids:
        try:
            results[uid] = send_notification(uid, message, notif_type, priority, retry_count, dry_run)
